/* HEXA BATTLEGROUNDS setup — PART 27 OF 32. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-4', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🦷 + 🖌️\n\n(10 letters · starts with T)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🛏️ + 🪨\n\n(7 letters · starts with B)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🧠 + ⛈️\n\n(10 letters · starts with B)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["TOOTHBRUSH"]},{"label":"Picture 2 (Decoder)","accept":["BEDROCK"]},{"label":"Picture 3 (Intel)","accept":["BRAINSTORM"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: TO…, BE…, BR…', 'TOOTHBRUSH: tooth + brush | BEDROCK: bed + rock | BRAINSTORM: brain + storm', null, 25, 'published'), ('recovery-pic-0', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"☀️ + 🌻\n\n(9 letters · starts with S)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔑 + 🎹\n\n(8 letters · starts with K)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"☁️ + 🖥️\n\n(2 words: 5 + 9 · starts with C)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["SUNFLOWER"]},{"label":"Picture 2 (Decoder)","accept":["KEYBOARD"]},{"label":"Picture 3 (Intel)","accept":["CLOUDCOMPUTING","CLOUDCOMPUTER"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words. Answers start with: SU…, KE…, CL…', 'SUNFLOWER: sun + flower | KEYBOARD: key + board | CLOUD COMPUTING: cloud + computer → cloud computing', null, 25, 'published'), ('recovery-pic-1', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🐝 + 🍃\n\n(7 letters · starts with B)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🌊 + 🐎\n\n(8 letters · starts with S)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🕷️ + 🕸️ + 🌐\n\n(3 words: 5 + 4 + 3 · starts with W)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["BAYLEAF","BEELEAF"]},{"label":"Picture 2 (Decoder)","accept":["SEAHORSE"]},{"label":"Picture 3 (Intel)","accept":["WORLDWIDEWEB","WEBSITE","WWW"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words. Answers start with: BA…, SE…, WO…', 'BAYLEAF: bee (bay) + leaf | SEAHORSE: sea + horse | WORLD WIDE WEB: the world-wide web', null, 25, 'published'), ('mission-riddle-0', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have keys but open no locks. You type on me every day.\n\n(8 letters · starts with K)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"What has to be broken before you can use it? (Breakfast!)\n\n(3 letters · starts with E)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"I am tall when I am new and short when I am old. I give light.\n\n(6 letters · starts with C)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["KEYBOARD"]},{"label":"Riddle 2 (Decoder)","accept":["EGG","ANEGG"]},{"label":"Riddle 3 (Intel)","accept":["CANDLE","ACANDLE"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: KE…, EG…, CA…', 'KEYBOARD: a keyboard | EGG: an egg | CANDLE: a candle', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-riddle-1', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"What has hands and a face but cannot clap or smile?\n\n(5 letters · starts with C)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"What has a neck and a cap but no head? You drink from it.\n\n(6 letters · starts with B)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What gets wetter the more it dries? You use it after a bath.\n\n(5 letters · starts with T)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["CLOCK","ACLOCK","WATCH"]},{"label":"Riddle 2 (Decoder)","accept":["BOTTLE","ABOTTLE"]},{"label":"Riddle 3 (Intel)","accept":["TOWEL","ATOWEL"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: CL…, BO…, TO…', 'CLOCK: a clock | BOTTLE: a bottle | TOWEL: a towel', null, 25, 'published'), ('mission-riddle-2', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"What has many teeth but never bites? It fixes your hair.\n\n(4 letters · starts with C)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"What has four legs but cannot walk? You eat lunch on it.\n\n(5 letters · starts with T)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has a head and a tail but no body? It is money.\n\n(4 letters · starts with C)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["COMB","ACOMB"]},{"label":"Riddle 2 (Decoder)","accept":["TABLE","ATABLE"]},{"label":"Riddle 3 (Intel)","accept":["COIN","ACOIN"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: CO…, TA…, CO…', 'COMB: a comb | TABLE: a table | COIN: a coin', null, 25, 'published'), ('mission-riddle-3', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"What has one eye but cannot see? You use it with thread.\n\n(6 letters · starts with N)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"What falls from the sky but never gets hurt? You need an umbrella.\n\n(4 letters · starts with R)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has many pages and words but never speaks?\n\n(4 letters · starts with B)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["NEEDLE","ANEEDLE"]},{"label":"Riddle 2 (Decoder)","accept":["RAIN"]},{"label":"Riddle 3 (Intel)","accept":["BOOK","ABOOK"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: NE…, RA…, BO…', 'NEEDLE: a needle | RAIN: rain | BOOK: a book', null, 25, 'published'), ('mission-riddle-4', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I ring, I have a screen, and you carry me everywhere.\n\n(5 letters · starts with P)","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I am full of holes but still hold water. I clean dishes.\n\n(6 letters · starts with S)","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What goes up when you get older, and never comes down?\n\n(3 letters · starts with A)","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["PHONE","MOBILE","CELLPHONE","APHONE"]},{"label":"Riddle 2 (Decoder)","accept":["SPONGE","ASPONGE"]},{"label":"Riddle 3 (Intel)","accept":["AGE","YOURAGE"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns. Answers start with: PH…, SP…, AG…', 'PHONE: a phone | SPONGE: a sponge | AGE: your age', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-movie-0', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🚢 🧊 💔\n\n(7 letters · starts with T)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🦁 👑\n\n(3 words: 3 + 4 + 4 · starts with T)","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦖 🏞️ 🚙\n\n(2 words: 8 + 4 · starts with J)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["TITANIC"]},{"label":"Film 2 (Decoder)","accept":["THELIONKING","LIONKING"]},{"label":"Film 3 (Intel)","accept":["JURASSICPARK","JURASSICWORLD"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional. Answers start with: TI…, TH…, JU…', 'TITANIC: ship, iceberg, heartbreak | THE LION KING: lion + crown | JURASSIC PARK: dinosaur park', null, 25, 'published'), ('mission-movie-1', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🥋 🐼\n\n(3 words: 4 + 2 + 5 · starts with K)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"❄️ 👸 ⛄\n\n(6 letters · starts with F)","mono":false,"big":true},"intel":{"title":"Film 3","body":"🕷️ 👨 🏙️\n\n(9 letters · starts with S)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["KUNGFUPANDA"]},{"label":"Film 2 (Decoder)","accept":["FROZEN"]},{"label":"Film 3 (Intel)","accept":["SPIDERMAN"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional. Answers start with: KU…, FR…, SP…', 'KUNG FU PANDA: kung fu + panda | FROZEN: ice queen + snowman | SPIDERMAN: spider + man', null, 25, 'published'), ('mission-movie-2', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🔍 🐠\n\n(2 words: 7 + 4 · starts with F)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🧸 📖\n\n(2 words: 3 + 5 · starts with T)","mono":false,"big":true},"intel":{"title":"Film 3","body":"3️⃣ 🤪 🎓\n\n(2 words: 1 + 6 · starts with 3)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["FINDINGNEMO","NEMO"]},{"label":"Film 2 (Decoder)","accept":["TOYSTORY"]},{"label":"Film 3 (Intel)","accept":["3IDIOTS","THREEIDIOTS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional. Answers start with: FI…, TO…, 3 …', 'FINDING NEMO: finding + fish | TOY STORY: toy + story | 3 IDIOTS: three idiots at college', null, 25, 'published'), ('mission-movie-3', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🤼‍♀️ 👨‍👧‍👧 🥇\n\n(6 letters · starts with D)","mono":false,"big":true},"decoder":{"title":"Film 2","body":"⚡ 🧙‍♂️ 👓\n\n(2 words: 5 + 6 · starts with H)","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦈 🌊 🏊\n\n(4 letters · starts with J)","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["DANGAL"]},{"label":"Film 2 (Decoder)","accept":["HARRYPOTTER"]},{"label":"Film 3 (Intel)","accept":["JAWS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional. Answers start with: DA…, HA…, JA…', 'DANGAL: wrestling father and daughters | HARRY POTTER: scar, wizard, glasses | JAWS: shark attack', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
